mapper.select:
SELECT id, activity_id, user_id, status, contract_version, form_version, submitted_at, updated_at, cancelled_at, invalidated_at, invalidated_by, invalid_reason
FROM activity_registration WHERE activity_id = #{activityId}
AND status = #{status}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT id, activity_id, user_id, status, contract_version, form_version, form_data, submitted_at, updated_at, cancelled_at,
       invalidated_at, invalidated_by, invalid_reason, created_at, updated_at
FROM activity_registration WHERE activity_id = #{activityId}
AND status = #{status}
ORDER BY id DESC LIMIT #{limit}

SELECT COUNT(*) FROM activity_registration
WHERE activity_id = #{activityId} AND status IN (1, 2)
AND status = #{status}

SELECT activity_id, COUNT(*) AS submitted_count FROM activity_registration WHERE status = 1 AND activity_id IN
#{activityId}
GROUP BY activity_id

mapper.update:
UPDATE activity_registration
SET form_data = #{data}, updated_at = #{now}, contract_version = contract_version + 1
WHERE id = #{id} AND status = 1 AND contract_version = #{version}

UPDATE activity_registration
SET status = 2, cancelled_at = #{now}, updated_at = #{now}, contract_version = contract_version + 1
WHERE id = #{id} AND status = 1 AND contract_version = #{version}
